 readonly Data.AppDb db=new(); readonly BusinessService svc; readonly long companyId; DataGrid grid=new(); OnlineApiClient? online;
 public MainWindow(){InitializeComponent();svc=new BusinessService(db);companyId=svc.EnsureCompany();Dashboard_Click(this,new RoutedEventArgs());}
 Button B(string text,RoutedEventHandler click){var b=new Button{Content=text,Style=(Style)FindResource("PrimaryButton")};b.Click+=click;return b;}
 Button Secondary(string text,RoutedEventHandler click){var b=new Button{Content=text,Style=(Style)FindResource("SecondaryButton")};b.Click+=click;return b;}
 void Show(string title,UIElement content){PageTitle.Text=title;ContentFrame.Content=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Padding=new Thickness(28),Content=content};}
 StackPanel Header(string title,string subtitle,params Button[] buttons){var h=new StackPanel();h.Children.Add(new TextBlock{Text=title,Style=(Style)FindResource("PageTitle")});h.Children.Add(new TextBlock{Text=subtitle,Style=(Style)FindResource("Caption"),Margin=new Thickness(0,0,0,13)});var bar=new WrapPanel();foreach(var b in buttons)bar.Children.Add(b);h.Children.Add(bar);return h;}
 DataGrid Table(string sql,params (string,object)[] p){var d=svc.Query(sql,p);var t=new DataTable();foreach(var c in d.Columns)t.Columns.Add(c);foreach(var r in d.Rows)t.Rows.Add(r);return new DataGrid{ItemsSource=t.DefaultView,AutoGenerateColumns=true,IsReadOnly=true,Margin=new Thickness(0,12,0,0),CanUserAddRows=false,MinHeight=400,GridLinesVisibility=DataGridGridLinesVisibility.Horizontal,SelectionMode=DataGridSelectionMode.Single,AlternatingRowBackground=(Brush)FindResource("SurfaceBrush")};}
 Border Card(string title,string value)=>new(){Style=(Style)FindResource("Card"),Child=new StackPanel{Children={new TextBlock{Text=title,Style=(Style)FindResource("Caption")},new TextBlock{Text=value,Style=(Style)FindResource("MetricValue"),Margin=new Thickness(0,5,0,0)}}}};
 string Money(object? v)=>$"{Convert.ToDecimal(v??0):N2} MT"; decimal D(string s)=>decimal.Parse((s??"0").Replace(',','.'),System.Globalization.CultureInfo.InvariantCulture);void Error(Exception ex)=>MessageBox.Show(ex.Message,"AyGest",MessageBoxButton.OK,MessageBoxImage.Error);
 string[]? Form(string title,params (string label,string value)[] fields){var w=new Window{Title=title,Width=470,SizeToContent=SizeToContent.Height,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=(Brush)FindResource("BgBrush")};var p=new StackPanel{Margin=new Thickness(22)};var boxes=new List<TextBox>();foreach(var f in fields){p.Children.Add(new TextBlock{Text=f.label,Margin=new Thickness(4,7,4,2),FontWeight=FontWeights.SemiBold,Foreground=(Brush)FindResource("TextBrush")});var b=new TextBox{Text=f.value,Margin=new Thickness(4)};boxes.Add(b);p.Children.Add(b);}var ok=B("Guardar",(_,_)=>w.DialogResult=true);p.Children.Add(ok);w.Content=p;if(w.ShowDialog()!=true)return null;return boxes.Select(x=>x.Text.Trim()).ToArray();}
 string Setting(string key,string fallback=""){var r=svc.Query("SELECT value FROM app_settings WHERE key=@k",("@k",key)).Rows.FirstOrDefault();return r is null?fallback:Convert.ToString(r[0])??fallback;}
 void SetSetting(string key,string value)=>svc.Execute("INSERT INTO app_settings(key,value) VALUES(@k,@v) ON CONFLICT(key) DO UPDATE SET value=excluded.value",("@k",key),("@v",value));
 static string DeviceId(){using var sha=SHA256.Create();return Convert.ToHexString(sha.ComputeHash(Encoding.UTF8.GetBytes(Environment.MachineName+"|"+Environment.UserName))).ToLowerInvariant();}
 void Dashboard_Click(object s,RoutedEventArgs e){var p=new StackPanel();p.Children.Add(Header("Dashboard","Resumo operacional da empresa",B("Actualizar",(_,_)=>Dashboard_Click(this,new()))));var t=svc.Query("SELECT COUNT(*),COALESCE(SUM(total),0),COALESCE(SUM(vat),0) FROM invoices WHERE company_id=@c AND status='issued' AND date(created_at)=date('now')",("@c",companyId));var r=t.Rows.FirstOrDefault();var cards=new UniformGrid{Columns=4,Margin=new Thickness(0,10,0,20)};cards.Children.Add(Card("Vendas hoje",Money(r?[1])));cards.Children.Add(Card("IVA hoje",Money(r?[2])));var st=svc.Query("SELECT COUNT(*) FROM products WHERE company_id=@c AND active=1",("@c",companyId));cards.Children.Add(Card("Produtos",Convert.ToString(st.Rows.FirstOrDefault()?[0])??"0"));var low=svc.Query("SELECT COUNT(*) FROM products p JOIN stock s ON s.product_id=p.id WHERE p.company_id=@c AND s.quantity<=p.min_stock",("@c",companyId));cards.Children.Add(Card("Stock crítico",Convert.ToString(low.Rows.FirstOrDefault()?[0])??"0"));p.Children.Add(cards);p.Children.Add(Table("SELECT number,status,subtotal,vat,total,payment_method,created_at FROM invoices WHERE company_id=@c ORDER BY id DESC LIMIT 15",("@c",companyId)));Show("Dashboard",p);}
 void Products_Click(object s,RoutedEventArgs e){var add=B("+ Novo produto",(_,_)=>AddProduct());var deactivate=Secondary("Desactivar",(_,_)=>DeactivateProduct());var p=Header("Produtos","Catálogo, preços, IVA, categorias, unidades e stock mínimo",add,deactivate);grid=Table("SELECT p.id,p.name,COALESCE(c.name,'Sem categoria') categoria,COALESCE(u.abbreviation,'UN') unidade,p.sku,p.barcode,p.cost,p.price,p.vat_rate,p.min_stock,COALESCE(s.quantity,0) stock,p.active FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN units u ON u.id=p.unit_id LEFT JOIN stock s ON s.product_id=p.id WHERE p.company_id=@c ORDER BY p.name",("@c",companyId));p.Children.Add(grid);Show("Produtos",p);}
 void AddProduct(){var categories=svc.Query("SELECT id,name FROM categories WHERE company_id=@c ORDER BY name",("@c",companyId));var units=svc.Query("SELECT id,name,abbreviation FROM units WHERE company_id=@c AND active=1 ORDER BY name",("@c",companyId));var w=new Window{Title="Novo produto",Width=500,SizeToContent=SizeToContent.Height,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=(Brush)FindResource("BgBrush")};var p=new StackPanel{Margin=new Thickness(22)};var boxes=new List<TextBox>();void Add(string label,string value=""){p.Children.Add(new TextBlock{Text=label,Margin=new Thickness(4,6,4,2),FontWeight=FontWeights.SemiBold});var b=new TextBox{Text=value};boxes.Add(b);p.Children.Add(b);}Add("Nome");Add("SKU");Add("Código de barras");Add("Custo","0");Add("Preço de venda","0");Add("IVA %","16");Add("Stock mínimo","0");p.Children.Add(new TextBlock{Text="Categoria",Margin=new Thickness(4,6,4,2),FontWeight=FontWeights.SemiBold});var cat=new ComboBox{ItemsSource=categories.Rows.Cast<DataRow>().Select(x=>new Option(Convert.ToInt64(x[0]),Convert.ToString(x[1])!)).ToList(),DisplayMemberPath="Name"};cat.SelectedIndex=categories.Rows.Count>0?0:-1;p.Children.Add(cat);p.Children.Add(new TextBlock{Text="Unidade",Margin=new Thickness(4,6,4,2),FontWeight=FontWeights.SemiBold});var unit=new ComboBox{ItemsSource=units.Rows.Cast<DataRow>().Select(x=>new Option(Convert.ToInt64(x[0]),$"{x[1]} ({x[2]})")).ToList(),DisplayMemberPath="Name"};unit.SelectedIndex=units.Rows.Count>0?0:-1;p.Children.Add(unit);p.Children.Add(B("Guardar produto",(_,_)=>{try{if(string.IsNullOrWhiteSpace(boxes[0].Text))throw new InvalidOperationException("O nome do produto é obrigatório.");var c=cat.SelectedItem as Option;var u=unit.SelectedItem as Option;svc.AddProduct(companyId,boxes[0].Text.Trim(),boxes[1].Text.Trim(),boxes[2].Text.Trim(),D(boxes[3].Text),D(boxes[4].Text),D(boxes[5].Text),D(boxes[6].Text));var id=Convert.ToInt64(svc.Query("SELECT id FROM products WHERE company_id=@co AND name=@n ORDER BY id DESC LIMIT 1",("@co",companyId),("@n",boxes[0].Text.Trim())).Rows[0][0]);svc.Execute("UPDATE products SET category_id=@cat,unit_id=@unit WHERE id=@i AND company_id=@co",("@cat",c?.Id??(object)DBNull.Value),("@unit",u?.Id??(object)DBNull.Value),("@i",id),("@co",companyId));w.Close();Products_Click(this,new());}catch(Exception ex){Error(ex);}}));w.Content=p;w.ShowDialog();}
 record Option(long Id,string Name);
 void DeactivateProduct(){if(grid.SelectedItem is not DataRowView r)return;try{svc.Execute("UPDATE products SET active=0 WHERE id=@i AND company_id=@c",("@i",Convert.ToInt64(r["id"])),("@c",companyId));Products_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Customers_Click(object s,RoutedEventArgs e){var add=B("+ Novo cliente",(_,_)=>AddCustomer());var p=Header("Clientes","Cadastro e histórico comercial",add);p.Children.Add(Table("SELECT id,name,nuit,phone,email,address FROM customers WHERE company_id=@c AND active=1 ORDER BY name",("@c",companyId)));Show("Clientes",p);}
 void AddCustomer(){var f=Form("Novo cliente",("Nome",""),("NUIT",""),("Telefone",""),("E-mail",""));if(f==null)return;try{svc.AddCustomer(companyId,f[0],f[1],f[2],f[3]);Customers_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Suppliers_Click(object s,RoutedEventArgs e){var add=B("+ Novo fornecedor",(_,_)=>AddSupplier());var p=Header("Fornecedores","Cadastro e relacionamento de compras",add);p.Children.Add(Table("SELECT id,name,nuit,phone,email,address FROM suppliers WHERE company_id=@c ORDER BY name",("@c",companyId)));Show("Fornecedores",p);}
 void AddSupplier(){var f=Form("Novo fornecedor",("Nome",""),("NUIT",""),("Telefone",""),("E-mail",""));if(f==null)return;try{svc.AddSupplier(companyId,f[0],f[1],f[2],f[3]);Suppliers_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Stock_Click(object s,RoutedEventArgs e){var adjust=B("Ajustar stock",(_,_)=>AdjustStock());var history=Secondary("Movimentos",(_,_)=>StockMovements());var p=Header("Stock","Inventário, disponibilidade e movimentos",adjust,history);p.Children.Add(Table("SELECT p.id,p.name,p.sku,COALESCE(s.quantity,0) quantity,p.min_stock,(COALESCE(s.quantity,0)-p.min_stock) margin FROM products p LEFT JOIN stock s ON s.product_id=p.id WHERE p.company_id=@c AND p.active=1 ORDER BY p.name",("@c",companyId)));Show("Stock",p);}
 void AdjustStock(){var f=Form("Ajuste de stock",("ID do produto",""),("Quantidade (+/-)","0"),("Motivo","Ajuste manual"));if(f==null)return;try{var q=D(f[1]);var pid=long.Parse(f[0]);if(q==0)throw new InvalidOperationException("A quantidade deve ser diferente de zero.");var affected=svc.Query("SELECT s.quantity FROM stock s JOIN products p ON p.id=s.product_id WHERE s.product_id=@p AND p.company_id=@c",("@p",pid),("@c",companyId)).Rows.FirstOrDefault();if(affected is null)throw new InvalidOperationException("Produto sem registo de stock ou não pertence à empresa.");var current=Convert.ToDecimal(affected[0]);if(current+q<0)throw new InvalidOperationException("O ajuste não pode deixar o stock negativo.");svc.Execute("UPDATE stock SET quantity=quantity+@q WHERE product_id=@p",("@q",q),("@p",pid));svc.Execute("INSERT INTO stock_movements(product_id,type,quantity,reference,created_at) VALUES(@p,'ADJUST',@q,@r,@d)",("@p",pid),("@q",q),("@r",f[2]),("@d",DateTime.UtcNow.ToString("O")));Stock_Click(this,new());}catch(Exception ex){Error(ex);}}
 void StockMovements(){var p=Header("Movimentos de stock","Histórico de entradas, vendas e ajustes");p.Children.Add(Table("SELECT sm.id,p.name,sm.type,sm.quantity,sm.reference,sm.created_at FROM stock_movements sm JOIN products p ON p.id=sm.product_id WHERE p.company_id=@c ORDER BY sm.id DESC LIMIT 500",("@c",companyId)));Show("Movimentos de stock",p);}
 void Invoices_Click(object s,RoutedEventArgs e){var sell=B("+ Nova factura / POS",(_,_)=>NewInvoice());var cancel=Secondary("Anular seleccionada",(_,_)=>CancelSelected());var pdf=Secondary("PDF A4",(_,_)=>ExportSelectedInvoice());var p=Header("Facturação","Documentos, pagamentos, anulação, impressão e histórico",sell,cancel,pdf);grid=Table("SELECT i.id,i.number,i.status,i.subtotal,i.vat,i.total,COALESCE(pm.name,i.payment_method,'—') pagamento,i.created_at FROM invoices i LEFT JOIN payment_methods pm ON pm.id=i.payment_method_id WHERE i.company_id=@c ORDER BY i.id DESC",("@c",companyId));p.Children.Add(grid);Show("Facturação",p);}
 void CancelSelected(){if(grid.SelectedItem is not DataRowView row)return;var f=Form("Anular factura",("Motivo",""));if(f==null)return;try{if(string.IsNullOrWhiteSpace(f[0]))throw new InvalidOperationException("Indique o motivo da anulação.");svc.CancelInvoice(Convert.ToInt64(row["id"]),f[0]);Invoices_Click(this,new());}catch(Exception ex){Error(ex);}}
 void ExportSelectedInvoice(){if(grid.SelectedItem is not DataRowView row)return;try{var id=Convert.ToInt64(row["id"]);var h=svc.Query("SELECT i.number,COALESCE(pm.name,i.payment_method,'—'),COALESCE(c.name,'Consumidor final'),co.name,co.nuit FROM invoices i JOIN companies co ON co.id=i.company_id LEFT JOIN customers c ON c.id=i.customer_id LEFT JOIN payment_methods pm ON pm.id=i.payment_method_id WHERE i.id=@i AND i.company_id=@c",("@i",id),("@c",companyId)).Rows.First();var items=svc.Query("SELECT description,quantity,unit_price,vat_rate FROM invoice_items WHERE invoice_id=@i",("@i",id));var lines=items.Rows.Select(x=>(Convert.ToString(x[0])??"",Convert.ToDecimal(x[1]),Convert.ToDecimal(x[2]),Convert.ToDecimal(x[3])));var path=new InvoicePdfService().Generate(System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"AyGest","Facturas"),Convert.ToString(h[3])??"",Convert.ToString(h[4])??"",Convert.ToString(h[0])??"",Convert.ToString(h[2])??"",Convert.ToString(h[1])??"",lines);System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(path){UseShellExecute=true});}catch(Exception ex){Error(ex);}}
 void NewInvoice(){var products=svc.Query("SELECT p.id,p.name,p.price,p.vat_rate,COALESCE(s.quantity,0) stock FROM products p JOIN stock s ON s.product_id=p.id WHERE p.company_id=@c AND p.active=1 ORDER BY p.name",("@c",companyId));var payments=svc.Query("SELECT id,name,requires_reference FROM payment_methods WHERE company_id=@c AND active=1 ORDER BY sort_order,name",("@c",companyId));if(products.Rows.Count==0){MessageBox.Show("Cadastre produtos e dê entrada de stock primeiro.","AyGest");return;}if(payments.Rows.Count==0){MessageBox.Show("Cadastre pelo menos um método de pagamento em Configurações.","AyGest");return;}var w=new Window{Title="Nova factura / POS",Width=650,Height=620,Owner=this,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=(Brush)FindResource("BgBrush")};var sp=new StackPanel{Margin=new Thickness(22)};var combo=new ComboBox{Margin=new Thickness(4),ItemsSource=products.Rows.Cast<DataRow>().Select(r=>new ProductChoice(Convert.ToInt64(r[0]),Convert.ToString(r[1])!,Convert.ToDecimal(r[2]),Convert.ToDecimal(r[3]),Convert.ToDecimal(r[4]))).ToList(),DisplayMemberPath="Name"};combo.SelectedIndex=0;var qty=new TextBox{Text="1"};var pay=new ComboBox{ItemsSource=payments.Rows.Cast<DataRow>().Select(r=>new PaymentChoice(Convert.ToInt64(r[0]),Convert.ToString(r[1])!,Convert.ToInt32(r[2])!=0)).ToList(),DisplayMemberPath="Name"};pay.SelectedIndex=0;var cust=new TextBox();var reference=new TextBox{Visibility=Visibility.Collapsed};var refLabel=new TextBlock{Text="Referência do pagamento",Visibility=Visibility.Collapsed,Style=(Style)FindResource("Caption")};pay.SelectionChanged+=(s,e)=>{if(pay.SelectedItem is PaymentChoice pc&&pc.RequiresReference){reference.Visibility=Visibility.Visible;refLabel.Visibility=Visibility.Visible;}else{reference.Visibility=Visibility.Collapsed;refLabel.Visibility=Visibility.Collapsed;}};sp.Children.Add(new TextBlock{Text="Produto",Style=(Style)FindResource("Caption")});sp.Children.Add(combo);sp.Children.Add(new TextBlock{Text="Quantidade",Style=(Style)FindResource("Caption")});sp.Children.Add(qty);sp.Children.Add(new TextBlock{Text="ID cliente (opcional)",Style=(Style)FindResource("Caption")});sp.Children.Add(cust);sp.Children.Add(new TextBlock{Text="Método de pagamento",Style=(Style)FindResource("Caption")});sp.Children.Add(pay);sp.Children.Add(refLabel);sp.Children.Add(reference);sp.Children.Add(B("Emitir factura",(_,_)=>{try{var x=(ProductChoice)combo.SelectedItem;var pm=(PaymentChoice)pay.SelectedItem;var q=D(qty.Text);if(q<=0)throw new InvalidOperationException("A quantidade deve ser maior que zero.");if(q>x.Stock)throw new InvalidOperationException("Stock insuficiente para este produto.");if(pm is null)throw new InvalidOperationException("Seleccione o método de pagamento.");if(pm.RequiresReference&&string.IsNullOrWhiteSpace(reference.Text))throw new InvalidOperationException("Este método exige uma referência de pagamento.");long? customerId=null;if(!string.IsNullOrWhiteSpace(cust.Text))customerId=long.Parse(cust.Text);var id=svc.CreateInvoice(companyId,customerId,new[]{(x.Id,x.Name,q,x.Price,x.Vat)},pm.Name);svc.Execute("UPDATE invoices SET payment_method_id=@pm WHERE id=@i AND company_id=@c",("@pm",pm.Id),("@i",id),("@c",companyId));w.Close();MessageBox.Show($"Factura emitida com sucesso. ID: {id}","AyGest",MessageBoxButton.OK,MessageBoxImage.Information);Invoices_Click(this,new());}catch(Exception ex){Error(ex);}}));w.Content=sp;w.ShowDialog();}
 record ProductChoice(long Id,string Name,decimal Price,decimal Vat,decimal Stock);record PaymentChoice(long Id,string Name,bool RequiresReference);
 void Purchases_Click(object s,RoutedEventArgs e){var receive=B("+ Entrada de compra",(_,_)=>ReceivePurchase());var p=Header("Compras","Entradas de mercadoria e custos",receive);p.Children.Add(Table("SELECT number,status,total,vat,created_at FROM purchases WHERE company_id=@c ORDER BY id DESC",("@c",companyId)));Show("Compras",p);}
 void ReceivePurchase(){var f=Form("Entrada de compra",("ID produto",""),("Quantidade","1"),("Custo unitário","0"),("IVA %","16"),("Fornecedor ID",""));if(f==null)return;try{var pid=long.Parse(f[0]);var qty=D(f[1]);var cost=D(f[2]);var vat=D(f[3]);if(qty<=0||cost<0||vat<0)throw new InvalidOperationException("Valores da compra inválidos.");using var c=db.Open();using var tx=c.BeginTransaction();using var q=c.CreateCommand();q.Transaction=tx;q.CommandText="INSERT INTO purchases(company_id,supplier_id,number,total,vat,created_at) VALUES(@c,@s,@n,@t,@v,@d);SELECT last_insert_rowid()";q.Parameters.AddWithValue("@c",companyId);q.Parameters.AddWithValue("@s",string.IsNullOrWhiteSpace(f[4])?DBNull.Value:long.Parse(f[4]));q.Parameters.AddWithValue("@n",$"CP-{DateTime.Now:yyyyMMdd-HHmmss}");q.Parameters.AddWithValue("@t",qty*cost*(1+vat/100));q.Parameters.AddWithValue("@v",qty*cost*vat/100);q.Parameters.AddWithValue("@d",DateTime.UtcNow.ToString("O"));var id=Convert.ToInt64(q.ExecuteScalar());q.Parameters.Clear();q.CommandText="INSERT INTO purchase_items(purchase_id,product_id,quantity,unit_cost,line_total) VALUES(@i,@p,@q,@u,@t);UPDATE stock SET quantity=quantity+@q WHERE product_id=@p;INSERT INTO stock_movements(product_id,type,quantity,reference,created_at) VALUES(@p,'PURCHASE',@q,@r,@d)";q.Parameters.AddWithValue("@i",id);q.Parameters.AddWithValue("@p",pid);q.Parameters.AddWithValue("@q",qty);q.Parameters.AddWithValue("@u",cost);q.Parameters.AddWithValue("@t",qty*cost);q.Parameters.AddWithValue("@r",id);q.Parameters.AddWithValue("@d",DateTime.UtcNow.ToString("O"));q.ExecuteNonQuery();tx.Commit();Purchases_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Cash_Click(object s,RoutedEventArgs e){var p=Header("Financeiro / Caixa","Abertura, movimentos, reconciliação e fecho",B("Abrir caixa",(_,_)=>OpenCash()),B("Movimento",(_,_)=>CashMove()),B("Fechar caixa",(_,_)=>CloseCash()));p.Children.Add(Table("SELECT id,status,opening_amount,expected_amount,closing_amount,opened_at,closed_at FROM cash_sessions WHERE company_id=@c ORDER BY id DESC",("@c",companyId)));Show("Financeiro / Caixa",p);}
 void OpenCash(){var f=Form("Abrir caixa",("Fundo inicial","0"));if(f==null)return;try{var amount=D(f[0]);if(amount<0)throw new InvalidOperationException("O fundo inicial não pode ser negativo.");svc.OpenCash(companyId,amount);Cash_Click(this,new());}catch(Exception ex){Error(ex);}}
 long CurrentCash(){var r=svc.Query("SELECT id FROM cash_sessions WHERE company_id=@c AND status='open' LIMIT 1",("@c",companyId)).Rows.FirstOrDefault();return r is null?0:Convert.ToInt64(r[0]);}
 void CashMove(){var id=CurrentCash();if(id==0){MessageBox.Show("Abra primeiro o caixa.","AyGest");return;}var methods=svc.Query("SELECT name FROM payment_methods WHERE company_id=@c AND active=1 ORDER BY sort_order,name",("@c",companyId));var method=methods.Rows.Count>0?Convert.ToString(methods.Rows[0][0])!:"Dinheiro";var f=Form("Movimento de caixa",("Tipo (IN/OUT)","IN"),("Descrição",""),("Valor","0"),("Método",method));if(f==null)return;try{var type=f[0].ToUpperInvariant();if(type!="IN"&&type!="OUT")throw new InvalidOperationException("Tipo deve ser IN ou OUT.");var value=D(f[2]);if(value<=0)throw new InvalidOperationException("O valor deve ser maior que zero.");svc.CashMovement(id,type,f[1],value,f[3]);Cash_Click(this,new());}catch(Exception ex){Error(ex);}}
 void CloseCash(){var id=CurrentCash();if(id==0){MessageBox.Show("Não há caixa aberto.","AyGest");return;}var f=Form("Fechar caixa",("Valor contado","0"));if(f==null)return;try{var value=D(f[0]);if(value<0)throw new InvalidOperationException("O valor contado não pode ser negativo.");svc.CloseCash(id,value);Cash_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Reports_Click(object s,RoutedEventArgs e){var export=Secondary("Exportar CSV",(_,_)=>ExportReportCsv());var p=Header("Relatórios","Facturação, IVA, documentos, stock e desempenho",export);var t=svc.Query("SELECT COALESCE(SUM(total),0),COALESCE(SUM(vat),0),COUNT(*) FROM invoices WHERE company_id=@c AND status='issued'",("@c",companyId));var r=t.Rows.FirstOrDefault();var cards=new UniformGrid{Columns=3};cards.Children.Add(Card("Facturação",Money(r?[0])));cards.Children.Add(Card("IVA",Money(r?[1])));cards.Children.Add(Card("Documentos",Convert.ToString(r?[2])??"0"));p.Children.Add(cards);p.Children.Add(Table("SELECT p.name,p.sku,COALESCE(s.quantity,0) stock,p.min_stock,p.cost,p.price,(p.price-p.cost) margin FROM products p JOIN stock s ON s.product_id=p.id WHERE p.company_id=@c ORDER BY (s.quantity-p.min_stock)",("@c",companyId)));Show("Relatórios",p);}
 void ExportReportCsv(){var data=svc.Query("SELECT number,status,subtotal,vat,total,payment_method,created_at FROM invoices WHERE company_id=@c ORDER BY id DESC",("@c",companyId));var dlg=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName=$"AyGest-Relatorio-{DateTime.Now:yyyyMMdd-HHmm}.csv"};if(dlg.ShowDialog()!=true)return;var sb=new StringBuilder();sb.AppendLine(string.Join(";",data.Columns));foreach(var r in data.Rows)sb.AppendLine(string.Join(";",r.Select(x=>(x?.ToString()??"").Replace(";",","))));File.WriteAllText(dlg.FileName,sb.ToString(),Encoding.UTF8);MessageBox.Show("Relatório exportado.","AyGest",MessageBoxButton.OK,MessageBoxImage.Information);}
 void Sales_Click(object s,RoutedEventArgs e)=>Invoices_Click(s,e);
 void Users_Click(object s,RoutedEventArgs e){var add=B("+ Novo utilizador",(_,_)=>AddUser());var p=Header("Utilizadores","Perfis e acesso ao sistema",add);p.Children.Add(Table("SELECT id,name,username,role,active FROM users WHERE company_id=@c ORDER BY name",("@c",companyId)));Show("Utilizadores",p);}
 void AddUser(){var f=Form("Novo utilizador",("Nome",""),("Username",""),("Password",""),("Perfil","Operator"));if(f==null)return;try{if(string.IsNullOrWhiteSpace(f[0])||string.IsNullOrWhiteSpace(f[1])||string.IsNullOrWhiteSpace(f[2]))throw new InvalidOperationException("Preencha nome, username e password.");var hash=Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(f[2])));svc.Execute("INSERT INTO users(company_id,name,username,password_hash,role) VALUES(@c,@n,@u,@p,@r)",("@c",companyId),("@n",f[0]),("@u",f[1]),("@p",hash),("@r",f[3]));Users_Click(this,new());}catch(Exception ex){Error(ex);}}
 void Audit_Click(object s,RoutedEventArgs e){var p=Header("Auditoria","Histórico de operações do sistema");p.Children.Add(Table("SELECT action,entity,entity_id,details,created_at FROM audit_log WHERE company_id=@c ORDER BY id DESC LIMIT 500",("@c",companyId)));Show("Auditoria",p);}
 void Settings_Click(object s,RoutedEventArgs e){var name=new TextBox{Text=Setting("company_name","Minha Empresa")};var nuit=new TextBox{Text=Setting("company_nuit","")};var server=new TextBox{Text=Setting("server_url",Environment.GetEnvironmentVariable("AYGEST_SERVER_URL")??"")};var save=B("Guardar empresa",(_,_)=>{SetSetting("server_url",server.Text.Trim());SetSetting("company_name",name.Text.Trim());SetSetting("company_nuit",nuit.Text.Trim());MessageBox.Show("Configurações guardadas.");});var p=Header("Configurações","Tudo o que pode ser alterado pela empresa, sem valores fixos",save,B("Métodos de pagamento",(_,_)=>PaymentMethods()),B("Categorias",(_,_)=>Categories()),B("Unidades",(_,_)=>Units()),B("Taxas de IVA",(_,_)=>TaxRates()),B("Séries",(_,_)=>DocumentSeries()));p.Children.Add(new TextBlock{Text="Dados da empresa",Style=(Style)FindResource("SectionTitle")});p.Children.Add(new TextBlock{Text="Nome da empresa",Style=(Style)FindResource("Caption")});p.Children.Add(name);p.Children.Add(new TextBlock{Text="NUIT",Style=(Style)FindResource("Caption")});p.Children.Add(nuit);p.Children.Add(new TextBlock{Text="URL do servidor online",Style=(Style)FindResource("Caption")});p.Children.Add(server);p.Children.Add(new TextBlock{Text="Base de dados local: "+db.Path,Margin=new Thickness(4,15,4,4),Foreground=(Brush)FindResource("MutedBrush")});Show("Configurações",p);}
 void PaymentMethods(){var add=B("+ Novo método",(_,_)=>AddPaymentMethod());var toggle=Secondary("Activar / desactivar",(_,_)=>TogglePaymentMethod());var p=Header("Métodos de pagamento","Configure os métodos usados no POS e no caixa",add,toggle);grid=Table("SELECT id,name,code,active,requires_reference,sort_order FROM payment_methods WHERE company_id=@c ORDER BY sort_order,name",("@c",companyId));p.Children.Add(grid);Show("Métodos de pagamento",p);}
 void AddPaymentMethod(){var f=Form("Novo método de pagamento",("Nome",""),("Código",""),("Exige referência? (0/1)","0"),("Ordem","0"));if(f==null)return;try{if(string.IsNullOrWhiteSpace(f[0])||string.IsNullOrWhiteSpace(f[1]))throw new InvalidOperationException("Nome e código são obrigatórios.");var refv=int.Parse(f[2]);if(refv is <0 or >1)throw new InvalidOperationException("Exige referência deve ser 0 ou 1.");var order=int.Parse(f[3]);svc.Execute("INSERT INTO payment_methods(company_id,name,code,requires_reference,sort_order) VALUES(@c,@n,@code,@r,@o)",("@c",companyId),("@n",f[0]),("@code",f[1].ToUpperInvariant()),("@r",refv),("@o",order));PaymentMethods();}catch(Exception ex){Error(ex);}}
 void TogglePaymentMethod(){if(grid.SelectedItem is not DataRowView r)return;try{svc.Execute("UPDATE payment_methods SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=@i AND company_id=@c",("@i",Convert.ToInt64(r["id"])),("@c",companyId));PaymentMethods();}catch(Exception ex){Error(ex);}}
 void Categories(){var add=B("+ Nova categoria",(_,_)=>AddCategory());var remove=Secondary("Eliminar seleccionada",(_,_)=>RemoveCategory());var p=Header("Categorias","Organize o catálogo sem categorias fixas no código",add,remove);grid=Table("SELECT id,name FROM categories WHERE company_id=@c ORDER BY name",("@c",companyId));p.Children.Add(grid);Show("Categorias",p);}
 void AddCategory(){var f=Form("Nova categoria",("Nome",""));if(f==null)return;try{if(string.IsNullOrWhiteSpace(f[0]))throw new InvalidOperationException("O nome da categoria é obrigatório.");svc.Execute("INSERT INTO categories(company_id,name) VALUES(@c,@n)",("@c",companyId),("@n",f[0]));Categories();}catch(Exception ex){Error(ex);}}
 void RemoveCategory(){if(grid.SelectedItem is not DataRowView r)return;var id=Convert.ToInt64(r["id"]);var used=svc.Query("SELECT COUNT(*) FROM products WHERE category_id=@i AND company_id=@c",("@i",id),("@c",companyId));if(Convert.ToInt32(used.Rows[0][0])>0){MessageBox.Show("Esta categoria está associada a produtos. Altere os produtos antes de a eliminar.","AyGest",MessageBoxButton.OK,MessageBoxImage.Warning);return;}try{svc.Execute("DELETE FROM categories WHERE id=@i AND company_id=@c",("@i",id),("@c",companyId));Categories();}catch(Exception ex){Error(ex);}}
 void Units(){var add=B("+ Nova unidade",(_,_)=>AddUnit());var toggle=Secondary("Activar / desactivar",(_,_)=>ToggleUnit());var p=Header("Unidades","Defina unidades como UN, KG, L, CX e outras",add,toggle);grid=Table("SELECT id,name,abbreviation,active FROM units WHERE company_id=@c ORDER BY name",("@c",companyId));p.Children.Add(grid);Show("Unidades",p);}
 void AddUnit(){var f=Form("Nova unidade",("Nome",""),("Abreviatura",""));if(f==null)return;try{if(string.IsNullOrWhiteSpace(f[0])||string.IsNullOrWhiteSpace(f[1]))throw new InvalidOperationException("Nome e abreviatura são obrigatórios.");svc.Execute("INSERT INTO units(company_id,name,abbreviation) VALUES(@c,@n,@a)",("@c",companyId),("@n",f[0]),("@a",f[1].ToUpperInvariant()));Units();}catch(Exception ex){Error(ex);}}
 void ToggleUnit(){if(grid.SelectedItem is not DataRowView r)return;try{svc.Execute("UPDATE units SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=@i AND company_id=@c",("@i",Convert.ToInt64(r["id"])),("@c",companyId));Units();}catch(Exception ex){Error(ex);}}
 void TaxRates(){var add=B("+ Nova taxa",(_,_)=>AddTaxRate());var toggle=Secondary("Activar / desactivar",(_,_)=>ToggleTaxRate());var p=Header("Taxas de IVA","Taxas configuráveis por empresa e sem percentagens fixas no POS",add,toggle);grid=Table("SELECT id,name,rate,active FROM tax_rates WHERE company_id=@c ORDER BY rate,name",("@c",companyId));p.Children.Add(grid);Show("Taxas de IVA",p);}
 void AddTaxRate(){var f=Form("Nova taxa de IVA",("Nome",""),("Percentagem","0"));if(f==null)return;try{var rate=D(f[1]);if(string.IsNullOrWhiteSpace(f[0])||rate<0||rate>100)throw new InvalidOperationException("Indique uma taxa entre 0 e 100.");svc.Execute("INSERT INTO tax_rates(company_id,name,rate) VALUES(@c,@n,@r)",("@c",companyId),("@n",f[0]),("@r",rate));TaxRates();}catch(Exception ex){Error(ex);}}
 void ToggleTaxRate(){if(grid.SelectedItem is not DataRowView r)return;try{svc.Execute("UPDATE tax_rates SET active=CASE WHEN active=1 THEN 0 ELSE 1 END WHERE id=@i AND company_id=@c",("@i",Convert.ToInt64(r["id"])),("@c",companyId));TaxRates();}catch(Exception ex){Error(ex);}}
 void DocumentSeries(){var add=B("+ Nova série",(_,_)=>AddSeries());var p=Header("Séries de documentos","Configure prefixos e numeração por empresa",add);grid=Table("SELECT id,name,prefix,next_number,active FROM document_series WHERE company_id=@c ORDER BY name",("@c",companyId));p.Children.Add(grid);Show("Séries de documentos",p);}
 void AddSeries(){var f=Form("Nova série",("Nome","Factura"),("Prefixo","FT"),("Próximo número","1"));if(f==null)return;try{var next=long.Parse(f[2]);if(string.IsNullOrWhiteSpace(f[0])||string.IsNullOrWhiteSpace(f[1])||next<1)throw new InvalidOperationException("Dados da série inválidos.");svc.Execute("INSERT INTO document_series(company_id,name,prefix,next_number) VALUES(@c,@n,@p,@next)",("@c",companyId),("@n",f[0]),("@p",f[1].ToUpperInvariant()),("@next",next));DocumentSeries();}catch(Exception ex){Error(ex);}}
 async void License_Click(object s,RoutedEventArgs e){var key=new TextBox{Width=420,Padding=new Thickness(10),Margin=new Thickness(0,10,0,8),Text=Setting("license_key")};var verify=B("Verificar licença",async(_,_)=>await VerifyLicense());var p=Header("Licenciamento","Activation Key online, tenant, plano e validade",verify);p.Children.Add(new TextBlock{Text="Activation Key",FontSize=16,FontWeight=FontWeights.Bold});p.Children.Add(key);p.Children.Add(B("Activar online",async(_,_)=>{try{var url=Setting("server_url",Environment.GetEnvironmentVariable("AYGEST_SERVER_URL")??"");if(string.IsNullOrWhiteSpace(url))throw new InvalidOperationException("Configure primeiro a URL do servidor em Configurações.");online?.Dispose();online=new OnlineApiClient(url);var result=await online.ActivateAsync(key.Text.Trim(),DeviceId(),Setting("tenant_id"));if(!result.Active)throw new InvalidOperationException(result.Message??"Licença recusada.");SetSetting("license_key",key.Text.Trim().ToUpperInvariant());if(!string.IsNullOrWhiteSpace(result.TenantId))SetSetting("tenant_id",result.TenantId!);SetSetting("license_plan",result.Plan??"");SetSetting("license_expires",result.ExpiresAt??"");StatusText.Text="Online • Licença activa";MessageBox.Show($"Licença activa. Tenant: {result.TenantId}\nPlano: {result.Plan}\nValidade: {result.ExpiresAt}");}catch(Exception ex){Error(ex);}}));p.Children.Add(new TextBlock{Text=$"Tenant: {Setting("tenant_id","—")}\nPlano: {Setting("license_plan","—")}\nExpira: {Setting("license_expires","—")}",Margin=new Thickness(4,15,4,4)});Show("Licenciamento",p);}
 async Task VerifyLicense(){try{var key=Setting("license_key");var url=Setting("server_url",Environment.GetEnvironmentVariable("AYGEST_SERVER_URL")??"");if(string.IsNullOrWhiteSpace(key)||string.IsNullOrWhiteSpace(url))throw new InvalidOperationException("Configure servidor e Activation Key.");online?.Dispose();online=new OnlineApiClient(url);var r=await online.VerifyAsync(key,DeviceId(),Setting("tenant_id"));StatusText.Text=r.Active?"Online • Licença válida":"Online • Licença inválida";MessageBox.Show(r.Message??(r.Active?"Licença válida.":"Licença inválida."));}catch(Exception ex){Error(ex);}}
}